import{_ as a,c as e,o as i,a5 as o}from"./chunks/framework.BTBXp1_p.js";const p=JSON.parse('{"title":"ADR-004: Conditional OAuth State Validation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-conditional-state-validation.md","filePath":"adr/004-conditional-state-validation.md","lastUpdated":1769357072000}'),r={name:"adr/004-conditional-state-validation.md"};function n(l,t,s,d,c,h){return i(),e("div",null,[...t[0]||(t[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /oauth-callback/adr/004-conditional-state-validation.md for this page in Markdown format</div><h1 id="adr-004-conditional-oauth-state-validation" tabindex="-1">ADR-004: Conditional OAuth State Validation <a class="header-anchor" href="#adr-004-conditional-oauth-state-validation" aria-label="Permalink to “ADR-004: Conditional OAuth State Validation”">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2025-01-25 <strong>Tags:</strong> oauth, security, csrf</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>RFC 6749 recommends <code>state</code> for CSRF protection, but RFC 8252 (native apps) relies on loopback redirect for security.</li><li>Some authorization servers don&#39;t echo <code>state</code> back; others require it.</li><li>Strict validation breaks compatibility; no validation weakens security.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Validate <code>state</code> only if it was present in the authorization URL.</li><li>If the auth URL includes <code>state</code> and the callback doesn&#39;t match, reject as CSRF.</li><li>If the auth URL omits <code>state</code>, accept callbacks without state validation.</li></ul><p>Rationale:</p><ul><li><strong>Defense-in-depth</strong>: Loopback binding (127.0.0.1) prevents network CSRF, but state adds protection against local attacks (malicious apps, browser extensions intercepting localhost).</li><li><strong>CLI threat model</strong>: Unlike web apps, CLI tools face local machine threats—other processes can probe localhost ports. State validation detects if a callback arrives from an unrelated auth flow.</li><li><strong>Compatibility</strong>: Authorization servers have inconsistent state handling. Conditional validation works with all servers while providing protection when available.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>Always require state</strong> — Breaks servers that don&#39;t echo state or don&#39;t support it.</li><li><strong>Never validate state</strong> — Loopback provides baseline security, but ignores state when the AS cooperates.</li><li><strong>Generate state internally always</strong> — Conflicts with auth URLs that already include state from the MCP SDK.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: Maximum security when AS supports state; universal compatibility otherwise.</li><li>Negative/Risks: If an AS echoes arbitrary state values without validation, the protection is weaker (rare edge case).</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code: <code>src/auth/browser-auth.ts:297-300</code></li><li>RFC 6749 Section 10.12 (CSRF Protection)</li><li>RFC 8252 Section 8.1 (Loopback Redirect)</li></ul>',15)])])}const b=a(r,[["render",n]]);export{p as __pageData,b as default};
